def main():
    N = int(input())

    scoreTakahashi = 0
    scoreAoki = 0
    for i in range(N):
        X, Y = map(int, input().split())
        scoreTakahashi += X
        scoreAoki += Y
    if scoreTakahashi > scoreAoki:
        print('Takahashi')
    elif scoreTakahashi < scoreAoki:
        print('Aoki')
    else:
        print('draw')
